import {readFile,writeFile,appendFile} from 'node:fs/promises';
import {runResearchLedger} from './research-ledger.mjs';
const prefix='artifacts/openai-source-review-20261008',observedAt=new Date().toISOString();
const write=(suffix,value)=>writeFile(prefix+suffix,typeof value==='string'?value:JSON.stringify(value,null,2)+'\n',{flag:'wx'});
await write('-watch.json',JSON.parse(await readFile('.runtime/research-watch/latest.json','utf8')));
await write('-report.md',`# 공식 OpenAI 원문 재검토\n\n관측 ${observedAt}. 6출처 중 raw HTML hash 변경3곳, 변화없음3곳,오류0. 변경된 이전 원문이 저장되지 않아 정확한 diff나 변경 시점을 확정하지 않는다. 최신 원문을 다시 읽은 사실과 새 출시 판정을 구분한다.\n\n[Agents API](https://developers.openai.com/api/docs/guides/agents-api/overview)는 관리형 세션·압축·복구와 실행환경 선택을 제공한다. 모델/도구/호스트 컨테이너 비용이 별도이므로 JARVIS Mission 원장을 대체하거나 무료 상시노드로 취급하지 않는다. [SDK](https://developers.openai.com/api/docs/guides/agents/sdk)는 앱이 저장소·도구·승인·배포를 소유하는 경로다. 기존 후보의 SDK maintenance 문구를 이번 페이지의 사실로 반복하지 않는다.\n\n[Changelog](https://developers.openai.com/api/docs/changelog)에서10월7일 chat-latest snapshot 갱신,10월6일 Decisions API beta/gpt-6-luna를 확인했다. chat-latest는 변동 alias이므로 고정 비교 기준을 자동 교체하지 않는다. [Decisions 원문](https://developers.openai.com/api/docs/guides/decisions)은 텍스트/이미지의 predicate·choice·score를 반환하는 전용 POST /v1/decisions,현재 gpt-6-luna 단일모델, JS SDK7.30.0 이상을 안내한다. '10배 빠름'은 제공자 설명이며 JARVIS 실측이 아니다.\n\n실제 부족 기능인 복합 요청의 분류·불확실성 판단 보조 후보로 검토할 가치가 있다. E 권한·금액·금지 검사나 G 파일/공급자 결과 대조를 확률 답변으로 대체하지 않는다. 기존 결정형 분류/Responses 대비 고정 공개·합성 사례에서 요구 누락·부정·정정·거부·실제 비용·p50/p95를 비교한 뒤 승격해야 한다. 실제 API 실행·계정·비용·효과·10배 개선은 미측정이며 설치/제품 활성화는 수행하지 않았다. 개인 자료 외부 전송 없음. 공식60/100 유지.\n`);
await write('-attempt.json',{id:'openai-source-review-20261008',candidateId:'openai-agents-api-runtime-selection',kind:'source-review',reportedOutcome:'inconclusive',observedAt,hypothesis:'Current official agent runtime documentation and new typed decision API may help JARVIS routing without replacing local authority or result verification.',lesson:'Reviewed current API/SDK division and dated changelog. Decisions beta is a bounded routing/evaluation candidate; provider speed claims require fixed independent comparison.',limitations:'No preserved previous HTML diff, API calls, credentials, cost measurement, installation or product activation; source review does not prove JARVIS improvement.',evidencePaths:[prefix+'-report.md',prefix+'-watch.json']});
console.log(JSON.stringify(runResearchLedger(['record',prefix+'-attempt.json'])));
await appendFile('docs/execution-to-100.md',`\n공식 원문 재검토 ${prefix}-report.md: SDK/API 경계 재확인, Decisions beta를 분류보조 비교 후보로 기록. 공급자10배 주장은 실측아님; API호출/활성화/진행률 승격없음.\n`);
